var EXTRA=[{"dot": "gray", "j": "Arthroplast Today", "h": "Infezione dopo UKA: debridement e infusione intrarticolare, esiti simili con coltura negativa", "v": "Coorte monocentrica esplorativa: l'eradicazione è simile con coltura positiva e negativa, ma con coltura negativa più degenza, costi e danno renale; il campione è troppo piccolo per concludere sull'equivalenza.", "pmid": "42866640", "doi": "10.1016/j.artd.2026.102171", "temi": ["UKA", "infezione periprotesica", "DAIR"]}, {"dot": "gray", "j": "J Robot Surg", "h": "TC preoperatoria: un modello misura il volume degli osteofiti per la TKA robotica", "v": "Rete neurale valutata contro annotazioni di esperti in due coorti esterne e contro gli osteofiti asportati in sala: accordo alto, volume stimato per difetto; è uno strumento di pianificazione, senza esiti clinici.", "pmid": "42837082", "doi": "10.1007/s11701-026-04015-y", "temi": ["TKA robotica", "osteofiti", "TC"]}, {"dot": "gray", "j": "Res Health Serv Reg", "h": "Fisioterapia dopo LCA e menisco in Germania: l'indagine fra i terapisti", "v": "Questionario online: l'esercizio terapeutico domina la prescrizione, in quantità già oltre i valori del catalogo tedesco dopo LCA, e per oltre la metà dei rispondenti l'attesa supera due settimane; è un sondaggio, non un confronto di esiti.", "pmid": "42837055", "doi": "10.1007/s43999-026-00091-7", "temi": ["riabilitazione", "LCA", "menisco"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "TKA nel varo: i sintomi alla caviglia seguono l'allineamento del retropiede dopo l'intervento", "v": "Coorte osservazionale piccola: l'inclinazione dell'astragalo e l'angolo del retropiede dopo la protesi sono fattori indipendenti di caviglia peggiorata, soprattutto con artrosi di caviglia preesistente; causalità non provata.", "pmid": "42843683", "doi": "10.1016/j.arth.2026.09.052", "temi": ["TKA", "caviglia", "allineamento"]}, {"dot": "gray", "j": "Arthroplast Today", "h": "Cortisone nel ginocchio opposto il giorno della TKA: nessuna differenza di complicanze", "v": "Coorte retrospettiva su artrosi bilaterale: complicanze e dolore senza differenze significative rispetto ai controlli; l'infezione è un evento raro e lo studio, a mio giudizio, non è dimensionato per escluderne un aumento.", "pmid": "42866287", "doi": "10.1016/j.artd.2026.102172", "temi": ["TKA", "infiltrazioni", "complicanze"]}, {"dot": "gray", "j": "BMC Sports Sci Med Rehabil", "h": "Fatica degli hamstring in atterraggio: meno flessione, più taglio tibiale anteriore", "v": "Studio di laboratorio randomizzato su atleti giovani: dopo fatica degli hamstring il ginocchio si flette meno e il taglio tibiale anteriore sale più che dopo fatica del quadricipite; dato biomeccanico, senza infortuni misurati.", "pmid": "42829434", "doi": "10.1186/s13102-026-02103-y", "temi": ["LCA", "prevenzione", "biomeccanica"]}, {"dot": "gray", "j": "Clin J Sport Med", "h": "Dolore femororotuleo nei corridori: la rieducazione del passo in una scoping review", "v": "Rassegna esplorativa con soli tre RCT: cadenza, riduzione dell'impatto e appoggio del piede riducono dolore e carico femororotuleo; come ogni scoping review non pesa il rischio di bias.", "pmid": "42864740", "doi": "10.1097/JSM.0000000000001519", "temi": ["dolore femororotuleo", "corsa", "riabilitazione"]}, {"dot": "gray", "j": "Cartilage", "h": "Deficit di estensione e perdita di cartilagine: la mappa regionale dai dati OAI", "v": "RM quantitativa dall'Osteoarthritis Initiative: chi ha un deficit di estensione perde più cartilagine nella parte centrale dei condili; associazione trasversale, non dice se il deficit sia causa o effetto.", "pmid": "42863822", "doi": "10.1177/19476035261498127", "temi": ["cartilagine", "contrattura in flessione", "artrosi"]}, {"dot": "gray", "j": "J Orthop Sports Phys Ther", "h": "Dinamometro portatile: la forza di ginocchio e caviglia si misura in modo affidabile", "v": "Revisione sistematica con metanalisi e mappa delle lacune: affidabilità sufficiente per la maggior parte dei muscoli e delle posizioni, con fissazione esterna per quadricipite e hamstring; validità di criterio poco studiata. Per i test di rientro la misura è utile (valutazione mia).", "pmid": "42823646", "doi": "10.2519/jospt.2026.14091", "temi": ["forza", "rientro allo sport", "misura"]}, {"dot": "gray", "j": "Bone Joint J", "h": "Prevenzione dell'infezione periprotesica: aggiornamento a dieci anni delle linee guida", "v": "Annotazione sulle raccomandazioni perioperatorie più recenti per anca e ginocchio; l'abstract non riporta le singole raccomandazioni, quindi non le riassumo.", "pmid": "42853096", "doi": "10.1302/0301-620X.108B10.BJJ-2025-1731.R1", "temi": ["infezione periprotesica", "prevenzione", "linee guida"]}, {"dot": "gray", "j": "Res Nurs Health", "h": "Prehabilitation prima di protesi d'anca e ginocchio: beneficio funzionale incerto nei fragili", "v": "Revisione sistematica con metanalisi di RCT: miglioramento sulla funzione misurata a test, non su quella riferita; intervalli ampi, forte eterogeneità, pochissimi studi con fragilità validata; anca e ginocchio insieme.", "pmid": "42862017", "doi": "10.1002/nur.70130", "temi": ["prehabilitation", "TKA", "fragilità"]}];
var SCOPERTE=[{"t": "Un robot per la protesi monocompartimentale a piattaforma aperta, provato su ossi sintetici a Pechino", "v": "Robot cinese che accetta impianti di produttori diversi: due studenti senza esperienza robotica eseguono quaranta resezioni su modelli sintetici passando da un impianto all'altro senza perdere precisione. Vale la deviazione perché mostra la robotica svincolata dal produttore dell'impianto; ossi sintetici, due operatori, nessun paziente.", "pmid": "42865385", "doi": "10.3389/frobt.2026.1886514", "temi": ["robotica", "UKA", "Cina"]}, {"t": "I video sull'artrosi di ginocchio nei social cinesi: i più accurati sono i meno coinvolgenti", "v": "Analisi trasversale di trecento video su tre piattaforme cinesi: la completezza dell'informazione si associa a meno interazione degli utenti. Vale la deviazione perché mostra dove si informano oggi i pazienti; è uno studio descrittivo su una sola data di raccolta.", "pmid": "42866113", "doi": "10.3389/fdgth.2026.1868584", "temi": ["informazione al paziente", "social media", "Cina"]}, {"t": "Localizzatori artroscopici stampati in 3D per il LCA: un quadro per la manifattura su misura", "v": "Prospettiva dal Liaoning che usa i localizzatori stampati in 3D per la ricostruzione artroscopica del LCA come esempio di come il piano digitale arriva in sala. Vale la deviazione per il collegamento fra immagine, stampa e gesto artroscopico; è un'opinione, senza dati di pazienti.", "pmid": "42865543", "doi": "10.3389/fbioe.2026.1903071", "temi": ["stampa 3D", "LCA", "pianificazione digitale"]}];
var SOC={"1": {"video": "La pendenza della parte alta della tibia, vista di profilo, conta nella pianificazione di molti interventi al ginocchio. Uno studio croato su oltre tremila radiografie di ginocchia con artrosi, pubblicato a ottobre 2026, ha cercato se ci siano tipi ricorrenti di pendenza.\n\nNe ha trovati due: una pendenza più dolce, intorno ai tre gradi e mezzo, in poco più della metà dei casi, e una più marcata, intorno agli otto gradi e mezzo, nei restanti.\n\nIl limite: lo studio descrive soltanto. Non segue i pazienti e non dice se un tipo o l'altro porti a risultati diversi. Riguarda ginocchia artrosiche di persone di circa settant'anni. L'indicazione pratica è misurare la pendenza di profilo, senza dedurla dall'asse frontale.\nFonte: PubMed, PMID 42871761.", "linkedin": "Pendenza tibiale posteriore in 3337 ginocchia artrosiche: il k-means sulla sola PTS identifica un gruppo piatto (centroide 3,56°; 55,91%) e uno ripido (8,52°; 44,09%), silhouette 0,56. Nelle 464 ginocchia con CPAK nessuna categoria è sovra-rappresentata; apice distale 54,2% nel gruppo ripido contro 38,7% dell'apice neutro (p<0,01). Studio radiografico retrospettivo, livello IV, Zagabria, J Exp Orthop, ottobre 2026.\n\nLimiti: partizione di una variabile continua, CPAK nel solo 13,9%, nessun esito clinico, età mediana 69 anni, nessuna validazione esterna.\nFonte: PubMed, PMID 42871761.", "instagram": "Pendenza della tibia, vista di profilo: in oltre 3000 radiografie di ginocchia con artrosi si riconoscono due forme ricorrenti.\nCirca 3,6° in poco più della metà dei casi, circa 8,5° nel resto.\nL'asse frontale (CPAK) non le distingue.\nStudio descrittivo, senza esiti clinici.\nFonte: PubMed, PMID 42871761.", "pazienti": "Quando si pianifica un intervento al ginocchio, si guarda anche quanto la parte alta della tibia è inclinata all'indietro. Un gruppo di ricercatori croati ha misurato questa inclinazione su più di tremila radiografie di ginocchia con artrosi.\n\nLo studio osserva soltanto e riguarda persone sui settant'anni con artrosi. Non dice quale forma sia preferibile, né che cosa cambi per chi si opera. Ciò che conta per ciascuno si decide con il chirurgo.\nFonte: PubMed, PMID 42871761."}};
var SOCV={"1": {"video": {"chir": ["Pendenza tibiale posteriore in 3337 ginocchia artrosiche, studio di Zagabria sul Journal of Experimental Orthopaedics, ottobre 2026. Il k-means, applicato alla sola pendenza, ha trovato due gruppi: uno piatto, centrato a 3,56 gradi, con il 55,9% delle ginocchia, e uno ripido, a 8,52 gradi, con il 44,1%. La silhouette media è 0,56, cioè una separazione moderata.", "Nelle 464 ginocchia con radiografia dell'arto intero, nessuna categoria CPAK risulta sovra-rappresentata in un gruppo. Raggruppando per orientamento della rima, l'apice distale cade più spesso nel gruppo ripido, 54,2% contro 38,7%, p minore di 0,01. La correlazione fra pendenza e obliquità della rima è inversa e modesta, rho meno 0,30.", "Limiti: il k-means su una variabile partiziona sempre. Il CPAK c'è solo nel 13,9% delle ginocchia, non c'è alcun esito clinico, l'età mediana è 69 anni. Il messaggio pratico: la pendenza si misura sulla laterale, il CPAK non la sostituisce.\nFonte: PubMed, PMID 42871761."], "misto": ["La pendenza della parte alta della tibia, vista di profilo, conta nella pianificazione di molti interventi al ginocchio. Uno studio croato su oltre tremila radiografie di ginocchia con artrosi, pubblicato a ottobre 2026, ha cercato se ci siano tipi ricorrenti di pendenza.", "Ne ha trovati due: una pendenza più dolce, intorno ai tre gradi e mezzo, in poco più della metà dei casi, e una più marcata, intorno agli otto gradi e mezzo, nei restanti. Questi due tipi non coincidono con le categorie con cui si descrive l'asse della gamba nella radiografia frontale.", "Il limite: lo studio descrive soltanto. Non segue i pazienti e non dice se un tipo o l'altro porti a risultati diversi. Riguarda ginocchia artrosiche di persone di circa settant'anni. L'indicazione pratica è misurare la pendenza di profilo, senza dedurla dall'asse frontale.\nFonte: PubMed, PMID 42871761."], "pazienti": ["Quando si pianifica un intervento al ginocchio, si guarda anche quanto la parte alta della tibia è inclinata all'indietro. Un gruppo di ricercatori croati ha misurato questa inclinazione su più di tremila radiografie di ginocchia con artrosi.", "Ne è uscito che le inclinazioni tendono a raggrupparsi in due forme: una meno inclinata, più frequente, e una più inclinata. Questa inclinazione non si può ricavare dall'allineamento della gamba visto di fronte: va misurata sulla radiografia di profilo.", "Lo studio osserva soltanto e riguarda persone sui settant'anni con artrosi. Non dice quale forma sia preferibile, né che cosa cambi per chi si opera. Ciò che conta per ciascuno si decide con il chirurgo.\nFonte: PubMed, PMID 42871761."]}, "linkedin": {"chir": ["Pendenza tibiale posteriore in 3337 ginocchia artrosiche: il k-means sulla sola PTS identifica un gruppo piatto (centroide 3,56°; 55,91%) e uno ripido (8,52°; 44,09%), silhouette 0,56. Nelle 464 ginocchia con CPAK nessuna categoria è sovra-rappresentata; apice distale 54,2% nel gruppo ripido contro 38,7% dell'apice neutro (p<0,01). Studio radiografico retrospettivo, livello IV, Zagabria, J Exp Orthop, ottobre 2026.", "Misura con il metodo di Hohmann, cinque esaminatori (ICC interosservatore ≥0,8, intraosservatore >0,95); correlazione PTS-obliquità della rima ρ -0,300 (p<0,001).", "Limiti: partizione di una variabile continua, CPAK nel solo 13,9%, nessun esito clinico, età mediana 69 anni, nessuna validazione esterna.\nFonte: PubMed, PMID 42871761."], "misto": ["Pendenza della tibia di profilo: in oltre 3300 radiografie di ginocchia con artrosi, uno studio di Zagabria (J Exp Orthop, ottobre 2026) trova due tipi ricorrenti, uno intorno a 3,6 gradi e uno intorno a 8,5 gradi, che la classificazione abituale dell'allineamento sul piano frontale (CPAK) non distingue.", "Il dato conta nella pianificazione di legamenti, osteotomie e protesi, perché la pendenza va misurata e non dedotta dall'asse frontale.", "Limite: studio solo descrittivo, su ginocchia con artrosi, senza esiti clinici.\nFonte: PubMed, PMID 42871761."], "pazienti": ["Misurare di profilo l'inclinazione della parte alta della tibia aiuta a pianificare molti interventi al ginocchio. In uno studio su più di 3300 radiografie di ginocchia con artrosi si riconoscono due forme ricorrenti, una meno e una più inclinata.", "Questa inclinazione non si deduce dall'allineamento visto di fronte: va misurata a parte.", "Lo studio osserva soltanto e non dice quale forma sia preferibile.\nFonte: PubMed, PMID 42871761."]}, "instagram": {"chir": ["Pendenza tibiale: due cluster.", "3337 ginocchia artrosiche: 3,56° (55,9%) e 8,52° (44,1%); il CPAK non li separa.", "Livello IV, nessun esito clinico, CPAK nel 13,9%.\nFonte: PubMed, PMID 42871761."], "misto": ["Pendenza della tibia di profilo.", "Su oltre 3000 radiografie si riconoscono due forme tipiche, che l'asse frontale non distingue.", "Studio descrittivo, senza esiti.\nFonte: PubMed, PMID 42871761."], "pazienti": ["Inclinazione della tibia.", "In oltre 3000 radiografie compaiono due forme ricorrenti, non deducibili dall'asse della gamba.", "Studio che osserva soltanto: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42871761."]}, "reel": {"chir": ["Slope tibiale: due gruppi.", "3,56° e 8,52°, il CPAK non li separa.", "Livello IV, nessun esito.\nFonte: PubMed, PMID 42871761."], "misto": ["Pendenza della tibia.", "Due forme ricorrenti, che l'asse frontale non distingue.", "Studio solo descrittivo.\nFonte: PubMed, PMID 42871761."], "pazienti": ["Inclinazione della tibia.", "Due forme ricorrenti nelle radiografie.", "Si osserva, non si confronta: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42871761."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #ChirurgiaDelGinocchio #Radiologia", "instagram": "#ortopedia #ginocchio #pendenzatibiale #slope #artrosi #protesidiginocchio #osteotomia #chirurgiaortopedica #ortopediaticino #medicinabasatasulleprove", "kw": "pendenza tibiale, slope tibiale, ginocchio, allineamento, protesi di ginocchio"}};
var NLB={"1": {"prof": ["Slope tibiale: due gruppi in 3337 ginocchia artrosiche, in gran parte indipendenti dal CPAK", "Studio radiografico retrospettivo monocentrico (J Exp Orthop, ottobre 2026): il k-means sulla pendenza tibiale posteriore divide 3337 ginocchia in un gruppo piatto, centrato a 3,56° (55,91%), e uno ripido, a 8,52° (44,09%); nelle 464 ginocchia con CPAK nessuna categoria singola è sovra-rappresentata, mentre l'apice distale della rima si associa al gruppo ripido (54,2% contro 38,7%, p<0,01).", "Nota critica: il k-means su una variabile partiziona sempre, la silhouette 0,56 indica separazione moderata, il CPAK è disponibile solo nel 13,9% delle ginocchia, nessun esito clinico, ginocchia artrosiche di età mediana 69 anni."], "mix": ["Pendenza della tibia: due tipi di ginocchio, che la classificazione abituale non distingue", "In oltre tremila radiografie di ginocchia artrosiche, la pendenza all'indietro della parte alta della tibia, misurata di profilo, si raggruppa attorno a due valori: circa 3,6 gradi in poco più della metà dei casi e circa 8,5 gradi nei restanti. Il gruppo non coincide con le categorie con cui si descrive l'asse della gamba sulla radiografia frontale, quindi quella pendenza va misurata a parte.", "Nota sul limite: lo studio descrive e non segue i pazienti; non dice se una pendenza o l'altra renda più o meno probabile un problema, e riguarda ginocchia artrosiche di persone sui settant'anni."], "paz": ["Pendenza della tibia: nelle radiografie del ginocchio si riconoscono due forme tipiche", "Un gruppo di ricercatori ha misurato l'inclinazione all'indietro della parte alta della tibia in più di tremila ginocchia con artrosi e ha trovato due forme ricorrenti, una meno inclinata e una più inclinata. Questa inclinazione non si può dedurre dall'allineamento della gamba visto di fronte: va misurata sulla radiografia di profilo.", "Lo studio osserva soltanto: non dice quale forma sia preferibile né che cosa cambi per chi si opera. Ciò che conta per ciascuno si valuta con il chirurgo."], "kw": "pendenza tibiale, slope, ginocchio, allineamento"}, "2": {"prof": ["LCA con residuo conservato: segnale RM dell'innesto migliore a 3 mesi, nessuna differenza a 6", "Coorte comparativa di 48 pazienti (Orthop Surg, ottobre 2026): con la tecnica «tension suspension», a 3 mesi il segnale RM dell'innesto e la variazione del tunnel femorale differiscono dal gruppo senza residuo conservato (p<0,05); a 6 mesi le differenze scompaiono (SNQ prossimale p=0,058) e i punteggi Lysholm, IKDC e Tegner sono uguali.", "Nota critica: 30 contro 18 pazienti, assegnazione non descritta, surrogato RM, nessun dato di stabilità, tipo di innesto non dichiarato."], "mix": ["Crociato anteriore: conservare il moncone aiuta l'innesto nei primi mesi, poi la differenza si perde", "In 48 operati di legamento crociato anteriore, chi ha avuto il moncone del legamento conservato e ancorato in tensione mostrava alla risonanza un innesto più «maturo» a tre mesi; a sei mesi la differenza non c'era più, e anche i punteggi di funzione riferiti dai pazienti erano uguali.", "Nota sul limite: i gruppi sono piccoli e non è chiaro come siano stati formati; la risonanza è un indizio sulla maturazione, non una misura di quanto il ginocchio sia stabile."], "paz": ["Crociato anteriore: conservare il residuo del legamento ha un effetto solo nei primi mesi", "In uno studio su 48 persone operate di legamento crociato anteriore, conservare il residuo del legamento durante l'intervento si è associato a un tendine trapiantato dall'aspetto più maturo alla risonanza dopo tre mesi. A sei mesi non c'erano più differenze, né nella risonanza né nei punteggi di funzione.", "Lo studio è piccolo e breve: non dice se il ginocchio sia più stabile. Si discute con il chirurgo."], "kw": "legamento crociato anteriore, ricostruzione, residuo, risonanza"}, "3": {"prof": ["Lassità generalizzata: più collagene III nel semitendinoso, ma solo con Beighton ≥6 (36 ginocchia)", "Studio di laboratorio su 36 operati di LCA (Bone Joint Res, ottobre 2026): con Beighton ≥6 (13 contro 23) il collagene di tipo III del semitendinoso è maggiore (117,9 contro 130,0 su una scala invertita, p=0,036) e l'angolo di convergenza della rima in varo è 6,3° contro 4,6° (p=0,021); con soglie ≥4 e ≥5 nessuna differenza.", "Nota critica: una soglia su tre, nessuna correzione per confronti multipli, nessuna prova meccanica né esito clinico; segno della correlazione non interpretabile dall'abstract."], "mix": ["Crociato e iperlassità: il tendine del semitendinoso di chi è molto lasso contiene più collagene di tipo III", "In 36 persone operate di crociato anteriore con il tendine del semitendinoso, quelle con le articolazioni molto lasse (punteggio di Beighton almeno 6) avevano più collagene di tipo III, più flessibile, nel tendine prelevato; la differenza si vedeva però solo con questa soglia e non con le due più basse.", "Nota sul limite: nessuno ha provato la resistenza del tendine né seguito i pazienti nel tempo, quindi l'idea che il tendine sia più fragile resta un'ipotesi."], "paz": ["Articolazioni molto lasse: il tendine usato per il crociato può avere una composizione diversa", "Uno studio giapponese su 36 persone operate di legamento crociato anteriore ha confrontato il tendine prelevato nelle persone con articolazioni molto lasse e in quelle senza. Nelle prime, con un punteggio di lassità alto, il tendine conteneva una quota maggiore di un tipo di collagene più flessibile.", "Il significato per il ginocchio operato non è noto: il tendine non è stato messo alla prova in laboratorio e i pazienti non sono stati seguiti. Se ne parla con il chirurgo."], "kw": "legamento crociato, lassità articolare, semitendinoso, collagene"}, "4": {"prof": ["UKA: cemento residuo in 84 pazienti su 321 (26,16%), di solito silente", "Studio retrospettivo monocentrico su 321 protesi monocompartimentali (Arthroplasty, ottobre 2026): cemento residuo in 84 (26,16%), estruso in 66 (20,56%, tutti asintomatici o lievi), frammenti liberi in 18 (5,61%, sei reinterventi); inserto più sottile OR 2,59 (IC 95% 1,38-4,98).", "Nota critica: TC solo nei sintomatici, quindi prevalenza per difetto; nessun confronto, follow-up e tecnica di cementazione non riportati."], "mix": ["Protesi monocompartimentale: più di un paziente su quattro ha del cemento rimasto nel ginocchio", "In 321 persone con protesi monocompartimentale, le immagini dopo l'intervento mostravano cemento residuo in 84. Nella maggior parte il cemento rimasto a ridosso dell'impianto non dava sintomi o solo un lieve fastidio; i 18 con frammenti liberi nell'articolazione sono quelli in cui sei hanno avuto bisogno di un nuovo intervento.", "Nota sul limite: la TC è stata fatta solo a chi stava male, quindi la frequenza reale è probabilmente più alta; non c'è un gruppo di confronto."], "paz": ["Protesi al ginocchio parziale: a volte resta un po' di cemento, di solito senza conseguenze", "In uno studio su 321 persone con protesi parziale del ginocchio, in più di una su quattro le immagini dopo l'intervento mostravano un po' di cemento rimasto fuori posto. Nella maggior parte non causava sintomi; quando i frammenti si muovevano liberi nell'articolazione, in alcuni casi è servito un secondo intervento.", "Lo studio non dice con quale frequenza si ripresenti né cosa fare nel singolo caso: dipende dalla situazione e si valuta con il chirurgo."], "kw": "protesi monocompartimentale, cemento, complicanze, ginocchio"}, "5": {"prof": ["Passi al giorno: UKA 9150 contro TKA 7920 in UK Biobank, UKA simile ai controlli", "Studio osservazionale propensity-matched (Bone Joint Res, ottobre 2026): in 2283 partecipanti con accelerometro al polso, la UKA (162) fa +15,5% di passi rispetto alla TKA (860), 9150 contro 7920 al giorno (p<0,001), ed è simile ai controlli accoppiati; TKA e THA restano più basse. IC non riportati.", "Nota critica: l'indicazione alla UKA non è casuale e il matching corregge solo le variabili misurate; una sola settimana di rilevamento, nessun PROM, nessuna sopravvivenza dell'impianto."], "mix": ["Dopo la protesi al ginocchio: chi ha quella parziale cammina più di chi ha quella totale", "In un grande archivio britannico, persone con protesi parziale del ginocchio facevano in media 9150 passi al giorno, contro 7920 di quelle con protesi totale, e si muovevano come chi non aveva artrosi; le persone con protesi totale restavano più sedentarie.", "Nota sul limite: chi riceve una protesi parziale ha in partenza un'artrosi meno estesa e spesso è più in forma, e un'unica settimana di misura non dice come stia il ginocchio né quanto duri l'impianto."], "paz": ["Protesi parziale o totale del ginocchio: quanto si cammina dopo, in un grande studio britannico", "Un gruppo di ricerca ha misurato con un contapassi da polso l'attività di più di 2000 persone con una protesi di anca o di ginocchio. Chi aveva la protesi parziale del ginocchio faceva in media più passi di chi aveva quella totale, con valori simili a chi non ha artrosi.", "Chi ha una protesi parziale è anche chi, all'inizio, aveva un'artrosi più limitata: il confronto non dice quale protesi sia adatta a ciascuno. Si decide con il chirurgo."], "kw": "protesi del ginocchio, protesi parziale, attività, passi"}, "6": {"prof": ["Cisti pretibiale dopo LCA: sei casi su 446 con viti di PLLA, tutti con reazione da corpo estraneo", "Serie retrospettiva (J Long Term Eff Med Implants, 2026): sei cisti pretibiali a 2-4 anni da LCA con viti da interferenza in PLLA; istologia di granuloma da corpo estraneo, tunnel tibiale allargato, nessuna comunicazione con l'articolazione; dopo sbrigliamento e rimozione della vite sintomi risolti, nessuna recidiva.", "Nota critica: sei casi senza confronto, denominatore 446 senza follow-up della coorte (IC 95% di Wilson 0,6-2,9%, calcolo mio), valori dei punteggi non riportati."], "mix": ["Dopo il crociato: gonfiore sotto il ginocchio anni dopo, a volte causato dalla vite che si dissolve", "In sei persone su 446 operate di crociato anteriore con viti riassorbibili, dopo due-quattro anni è comparsa una cisti sotto il ginocchio: la rimozione della cisti e della vite ha risolto il problema senza recidive e senza perdita di stabilità, e l'esame del tessuto ha mostrato una reazione al materiale della vite.", "Nota sul limite: sono sei casi, senza gruppo di confronto, quindi non si può dire con quale frequenza accada né se altri materiali siano più o meno a rischio."], "paz": ["Dopo l'intervento al crociato: un gonfiore sotto il ginocchio che compare dopo anni", "Uno studio greco ha descritto sei persone, su 446 operate di legamento crociato con viti riassorbibili, che dopo due-quattro anni hanno avuto un gonfiore dolente sotto il ginocchio. Era dovuto a una reazione dell'organismo al materiale della vite; con un piccolo intervento di rimozione il problema si è risolto senza ripresentarsi.", "È una complicanza rara e lo studio è piccolo. Un gonfiore nuovo va fatto vedere al proprio chirurgo."], "kw": "legamento crociato, vite riassorbibile, cisti, complicanze"}, "7": {"prof": ["PFA robotica a 16 mesi: libera da revisione al 91,6% a 24 mesi (IC 95% 80,1-100,0), serie senza controllo", "Serie retrospettiva monocentrica di 30 pazienti, 35 ginocchia (SICOT J, ottobre 2026): reintervento 8,6% (3/35), due conversioni a TKA; KSS 110,7 → 163,7 (p<0,001), lateralizzazione rotulea 4,7 → 0,8 mm (p<0,001), rientro allo sport 78,3% degli attivi; follow-up medio 15,7 mesi.", "Nota critica: nessun gruppo convenzionale, quindi il ruolo del robot non è isolabile; tre eventi, follow-up breve per una PFA."], "mix": ["Protesi della rotula e della troclea con robot: buoni risultati nei primi due anni in una serie lionese", "In 35 ginocchia operate a Lione di protesi femororotulea con l'aiuto di un robot, a circa un anno e mezzo di distanza il punteggio funzionale era salito da 111 a 164 e la rotula era meglio centrata; tre ginocchia sono state rioperate, due con passaggio a protesi totale.", "Nota sul limite: manca un confronto con l'intervento senza robot, e il follow-up è breve per questo tipo di protesi."], "paz": ["Protesi al ginocchio solo dietro la rotula: buoni risultati iniziali con la guida di un robot", "Uno studio francese su 30 persone con artrosi limitata alla parte anteriore del ginocchio, operate con una protesi parziale guidata da un robot, ha trovato un miglioramento della funzione e della posizione della rotula dopo circa un anno e mezzo. Tre ginocchia su 35 sono state rioperate.", "Lo studio non confronta con l'intervento senza robot e segue i pazienti per poco tempo. Se ne parla con il chirurgo."], "kw": "protesi femororotulea, robot, rotula, artrosi"}, "8": {"prof": ["TKA: apertura mediale ≥1,5 mm al primo giorno, OKS peggiore nelle donne <70 anni (637 ginocchia)", "Coorte retrospettiva (Musculoskelet Surg, ottobre 2026): in 637 TKA con allineamento meccanico, nelle donne <70 anni ogni mm di apertura mediale alla radiografia in scarico del primo giorno si associa a 1 punto OKS in meno e 2,4 punti EQ-5D VAS in meno a 5,4 anni mediani; negli uomini nessuna associazione. IC non riportati.", "Nota critica: sottogruppo non dichiarato come pianificato, misura statica non equivalente al bilanciamento intraoperatorio, effetto di 1 punto OKS sotto la soglia clinica."], "mix": ["Protesi totale di ginocchio: lo spazio sbilanciato visto il primo giorno ha un peso solo nelle donne giovani", "In 637 protesi totali, quando nella radiografia del giorno dopo l'intervento lo spazio interno del ginocchio risultava più aperto di circa un millimetro e mezzo, le donne sotto i 70 anni avevano, dopo più di cinque anni, punteggi di funzione di poco più bassi; negli uomini non si vedeva nessun legame.", "Nota sul limite: la differenza è piccola, riguarda un sottogruppo, e una radiografia del primo giorno non misura come il ginocchio sia bilanciato in movimento."], "paz": ["Protesi totale al ginocchio: una piccola asimmetria nella radiografia del primo giorno e il risultato dopo anni", "Uno studio australiano su 637 protesi totali ha trovato che, nelle donne sotto i 70 anni, una leggera asimmetria dello spazio dell'articolazione visibile nella radiografia del primo giorno si associava a punteggi di funzione un po' più bassi dopo oltre cinque anni. Negli uomini non c'era nessun legame.", "Si tratta di una differenza piccola, osservata in un sottogruppo, che non permette di dire che cosa cambiare in un singolo caso. Se ne parla con il chirurgo."], "kw": "protesi totale ginocchio, radiografia, equilibrio legamentoso, risultati"}, "9": {"prof": ["Revisione di TKA: Delphi su una classificazione TC dei difetti ossei, consenso sul 93% delle affermazioni", "Studio Delphi (Bone Jt Open, ottobre 2026): 29 affermazioni da cinque interviste, 56 esperti invitati, 37 rispondenti al primo round e 34 al secondo; consenso (≥80%) sul 93%; la classificazione deve guidare pianificazione e scelta dell'impianto, la TC migliora la valutazione; nessun consenso sui riferimenti delle zone epifisi-metafisi-diafisi.", "Nota critica: opinione di esperti, nessun dato di paziente né validazione, composizione del panel non riportata."], "mix": ["Protesi di ginocchio da rivedere: gli esperti concordano sulla TC, non su dove finiscono le zone", "Un gruppo di esperti internazionali, chiamati a rispondere per due volte a un questionario, ha concordato che per pianificare l'intervento di revisione di una protesi di ginocchio serve una classificazione dei difetti dell'osso basata sulla TC. Non hanno trovato accordo su dove cominci e finisca ciascuna zona dell'osso.", "Nota sul limite: è un'opinione condivisa fra specialisti, senza pazienti; la classificazione proposta non è ancora stata provata."], "paz": ["Rivedere una protesi del ginocchio: gli specialisti discutono come descrivere i difetti dell'osso", "Un gruppo di specialisti di vari paesi ha cercato un accordo su come descrivere, con la TC, la perdita di osso attorno a una protesi di ginocchio da sostituire, per pianificare meglio l'intervento. Su gran parte dei punti si sono trovati d'accordo; su dove dividere le zone dell'osso, no.", "È un accordo fra esperti, non una nuova cura. Per ogni singolo caso decide il chirurgo."], "kw": "revisione protesi ginocchio, TC, difetti ossei, pianificazione"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"J Exp Orthop",h:"Pendenza tibiale posteriore: i ginocchi artrosici si dividono in due gruppi, che il CPAK non separa",v:"Studio radiografico retrospettivo monocentrico (Zagabria; livello IV): 3337 ginocchia artrosiche di 1746 pazienti, pendenza tibiale posteriore (PTS) mediana 5,6° (IQR 3,4°-7,7°). Il k-means sulla sola PTS dà due gruppi: «piatto» centrato a 3,56° (55,91%, 1866 ginocchia) e «ripido» a 8,52° (44,09%, 1471), silhouette media 0,56 (separazione moderata). Nelle 464 ginocchia con radiografia dell'arto intero, nessuna categoria CPAK è sovra-rappresentata in un gruppo; con rima articolare apice distale (CPAK I-III) il 54,2% sta nel gruppo ripido, con apice neutro (IV-VI) il 38,7% (p<0,01). PTS e obliquità della rima: correlazione inversa modesta (ρ -0,300; p<0,001).",ax:"Vidović, Blažević, Baković, Čukelj, Karakaš, Vojvodić, Barešić, Šmuc, Weinberger",date:"ott 2026",meta:"studio radiografico retrospettivo, 3337 ginocchia artrosiche (464 con CPAK), clustering k-means sulla pendenza tibiale posteriore · [livello IV]",pmid:'42871761',doi:'10.1002/jeo2.70945',journal:"Journal of experimental orthopaedics",authors:"Vidović D, Blažević D, Baković J, Čukelj F, Karakaš T, Vojvodić B, Barešić A, Šmuc T, Weinberger DG",design:"Studio radiografico retrospettivo monocentrico (Sestre Milosrdnice University Hospital Center, Zagabria), livello IV dichiarato: PTS misurata sulla laterale con il metodo di Hohmann (corticale posteriore e piatto mediale), cinque esaminatori con calibrazione su 100 radiografie (ICC interosservatore ≥0,8, intraosservatore >0,95). Esclusi artrosi post-traumatica, osteotomia correttiva pregressa e tumori periarticolari. K-means a una sola variabile (numero di gruppi con metodo del gomito e silhouette); sul sottogruppo con radiografia dell'arto intero MPTA, LDFA, aHKA, obliquità della rima (JLO) e fenotipo CPAK. Testo completo letto su PMC (PMC13660407).",pop:"3337 ginocchia di 1746 pazienti, età mediana 69 anni (IQR 63-73); 464 (13,9%) con radiografia dell'arto intero in carico, usate per il CPAK. Quota di donne: non riportata; PTS senza differenza fra i sessi (p=0,269). Esiti clinici: non raccolti.",results:"PTS mediana 5,6° (IQR 3,4°-7,7°); gruppo piatto 3,74° (IQR 2,42°-4,92°), gruppo ripido 8,02° (IQR 7,00°-9,48°); silhouette media 0,56. Distribuzione CPAK complessiva contro gruppi: p<0,05, ma nessuna cella singola significativa. Apice distale (I-III, 295 ginocchia): 54,2% ripido; apice neutro (IV-VI, 155): 38,7% (Fisher p<0,01). JLO 176° ± 4,39° nel piatto contro 174° ± 4,78° nel ripido (d di Cohen 0,43; IC 95% 0,25-0,62); MPTA mediana 87,3° contro 86,3° (Cliff 0,16; IC 95% 0,07-0,27). Correlazione PTS-JLO ρ -0,300 (p<0,001).",concl:"Gli autori: la PTS ha due fenotipi sagittali, in gran parte indipendenti dalle singole categorie CPAK; il CPAK, coronale, non può sostituire la misura diretta della pendenza.",limits:"Monocentrico retrospettivo; il CPAK esiste solo in 464 ginocchia su 3337 (13,9%): possibile bias di selezione · il k-means su una sola variabile divide sempre in gruppi: la silhouette 0,56 dice separazione moderata, non che esistano due popolazioni; nessuna validazione esterna · nessun esito clinico, ginocchia artrosiche di età avanzata (non LCA né osteotomia).",perte:"Ti tocca per le correzioni di slope e per il LCA: gli autori citano come soglia di rischio per il fallimento dell'innesto circa 10°-12°, sopra il centro del gruppo ripido (8,5°). Ma la casistica è artrosica, età mediana 69 anni: non il tuo LCA giovane. Cosa fare: nulla di nuovo; il solo appiglio pratico è che la pendenza va misurata sulla laterale, non dedotta dal CPAK, anche prima di impostare il piano con il robot."},
{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Orthop Surg",h:"LCA con residuo conservato «a sospensione in tensione»: segnale RM dell'innesto migliore a 3 mesi, non a 6",v:"Coorte comparativa (Shenzhen; livello non dichiarato): 48 operati di LCA monofascio anatomico, residuo conservato con tecnica «tension suspension» (30) contro residuo non conservato (18). RM a 3 e 6 mesi: rapporto segnale/rumore dell'innesto (SNQ) e variazione del diametro del tunnel femorale. A 3 mesi differenze significative (p<0,05), più marcate all'estremo distale; a 6 mesi nessuna differenza di SNQ (prossimale quasi significativa, p=0,058) né di tunnel, e punteggi Lysholm, IKDC e Tegner senza differenze. Il Tegner a 6 mesi correla con l'SNQ (p<0,05).",ax:"Liang, Huang, Yang, Wei, Yang, Huang, Zhu",date:"ott 2026",meta:"coorte comparativa, 48 pazienti, LCA monofascio con o senza residuo conservato, RM a 3 e 6 mesi · [livello non dichiarato]",pmid:'42870671',doi:'10.1111/os.70443',journal:"Orthopaedic surgery",authors:"Liang J, Huang G, Yang W, Wei J, Yang Y, Huang Z, Zhu W",design:"Coorte comparativa (Shenzhen University, Cina) di pazienti operati dal dicembre 2021 al giugno 2023, divisi in gruppo senza residuo conservato (NPR, 18) e con residuo conservato (PR, 30); l'abstract non descrive randomizzazione né criteri di assegnazione. RM a 3 e 6 mesi con misura del rapporto segnale/rumore dell'innesto (SNQ) in una regione di interesse e della variazione di diametro del tunnel femorale; Lysholm, IKDC e Tegner a 6 mesi; correlazione di Spearman fra SNQ e punteggi. Solo abstract letto: non risulta testo completo in PMC.",pop:"48 pazienti (NPR 18, PR 30), senza differenze di età, sesso, BMI e diametro dell'innesto. Tipo di innesto, età media, tecnica di fissazione, follow-up oltre i 6 mesi: non riportati nell'abstract.",results:"A 3 mesi differenze significative di SNQ (più marcate all'estremo distale) e di variazione del diametro del tunnel femorale (p<0,05); i valori non sono riportati nell'abstract. A 6 mesi nessuna differenza di SNQ (prossimale p=0,058) né di tunnel; Lysholm, IKDC e Tegner senza differenze fra i gruppi. Tegner correlato con l'SNQ a 6 mesi (correlazione da moderata a significativa, p<0,05); coefficienti non riportati.",concl:"Gli autori: la tecnica «tension suspension» con residuo conservato accelera la legamentizzazione precoce dell'innesto e riduce l'allargamento del tunnel femorale; la funzione soggettiva potrebbe legarsi all'intensità del segnale.",limits:"48 pazienti, 18 contro 30, assegnazione non descritta · il segnale RM è un surrogato e a 6 mesi la differenza scompare: nessun dato su stabilità o re-rottura · valori e IC non riportati nell'abstract; tipo di innesto non dichiarato.",perte:"Tocca il LCA ma non il tuo innesto né la tua scelta di base: l'abstract non dice quale tendine, e la maturazione dell'innesto vista alla RM è un indizio, non un esito. Cosa fare: nulla; nessun dato di stabilità o di re-rottura, e a sei mesi il vantaggio non c'è più."},
{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Bone Joint Res",h:"Lassità generalizzata: più collagene di tipo III nel semitendinoso prelevato per il LCA",v:"Studio prospettico non randomizzato di laboratorio (Fukuoka; livello non dichiarato): 36 ginocchia di 36 operati di LCA con semitendinoso, collagene di tipo I, III, V e XII nel frammento scartato all'inserzione tibiale, per immunoistochimica; lassità generalizzata (GJL) con Beighton ≥4, ≥5 o ≥6. Solo con Beighton ≥6 (13 contro 23) il collagene III differisce: valore 117,9 (DS 17,4) contro 130,0 (DS 11,5), p=0,036, su una scala in cui il valore più basso indica più collagene; con soglie ≥4 e ≥5 nessuna differenza (p=0,249 e p=0,053). Tipi I, V e XII invariati. Angolo di convergenza della rima in varo 6,3° (DS 1,9°) contro 4,6° (DS 2,0°), p=0,021; iperestensione sotto anestesia diversa con tutte le soglie.",ax:"Miyazaki, Maeyama, Ishimatsu, Matsunaga, Yamamoto",date:"ott 2026",meta:"studio prospettico non randomizzato, 36 ginocchia, immunoistochimica del semitendinoso, lassità generalizzata secondo Beighton · [livello non dichiarato]",pmid:'42869443',doi:'10.1302/2046-3758.1510.BJR-2025-0544.R1',journal:"Bone & joint research",authors:"Miyazaki K, Maeyama A, Ishimatsu T, Matsunaga T, Yamamoto T",design:"Studio prospettico, non randomizzato e sequenziale (Fukuoka University), LCA primario con semitendinoso dal 2019 al 2022: 72 ginocchia valutate, 36 incluse (28 escluse per disaccordo fra i due esaminatori sul Beighton). Frammento a circa 5 mm dalla parte più distale, all'inserzione tibiale, congelato a -80 °C; immunoistochimica per collagene I, III, V, XII e analisi d'immagine semiquantitativa in unità arbitrarie (valore basso = più collagene); radiografie da stress del lato sano. Test t o Mann-Whitney, Pearson fra Beighton e collagene. Testo completo letto su PMC (PMC13661152).",pop:"36 pazienti, età media 23,4 anni (DS 10,2), 21 uomini e 15 donne. Gruppi: Beighton ≥4: 18 contro 18; ≥5: 16 contro 20; ≥6: 13 contro 23. Esiti clinici e re-rotture: non raccolti.",results:"Collagene III con Beighton ≥6: 117,9 (DS 17,4) contro 130,0 (DS 11,5), p=0,036 (scala invertita: valore basso = più collagene); con ≥4: p=0,249; con ≥5: p=0,053. Collagene I, V, XII: nessuna differenza. Correlazione Beighton-collagene III 0,375 (p=0,024); segno non interpretabile dall'abstract data la scala invertita. JLCA in varo 6,3° (DS 1,9°) contro 4,6° (DS 2,0°), p=0,021 (solo con ≥6). Iperestensione del ginocchio sotto anestesia: p=0,004 (≥4), p=0,001 (≥5), p=0,001 (≥6).",concl:"Gli autori: nei pazienti con lassità generalizzata il semitendinoso contiene più collagene di tipo III, un tessuto più flessibile e forse più fragile; il dato apre la riflessione sulla scelta del tendine e sulle procedure aggiuntive.",limits:"36 ginocchia: l'effetto compare con una sola soglia di Beighton su tre (13 contro 23), senza correzione per confronti multipli; le soglie ≥4 e ≥5 non sono significative, e gli autori ammettono il possibile errore di tipo II · nessuna prova meccanica né analisi dell'innesto dopo l'impianto: la «fragilità» è dedotta dalla letteratura · metodo semiquantitativo con anticorpi diversi per ogni tipo, campioni congelati.",perte:"Innesto diverso: il tuo è il retto femorale, non il semitendinoso. Ti serve come ipotesi sul perché la lassità generalizzata è un fattore di rischio di re-rottura con l'hamstring, non come dato sul quadricipite. Cosa fare: nulla; resta il tuo rinforzo laterale universale, qui non studiato. Nessun dato di esito, solo istologia."},
{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Arthroplasty",h:"Protesi monocompartimentale: cemento residuo in oltre un paziente su quattro, di solito silente",v:"Studio retrospettivo monocentrico (Fuzhou; livello non dichiarato): 321 UKA, cemento residuo alle immagini postoperatorie in 84 pazienti (26,16%), di cui 66 (20,56%) con cemento estruso residuo (RCE) e 18 (5,61%) con frammenti liberi (FCF). Tutti i 66 RCE asintomatici o con lieve fastidio; 6 FCF reinterventi per dolore o limitazione. Inserto di polietilene più sottile: fattore di rischio (OR 2,59; IC 95% 1,38-4,98; p=0,005). La TC è stata fatta solo nei sintomatici, quindi 26,16% è una stima per difetto.",ax:"Yu, Wu, Lin, Chen, Bai, Fang, Zhang, Huang",date:"ott 2026",meta:"studio retrospettivo monocentrico, 321 UKA, cemento residuo alle immagini · [livello non dichiarato]",pmid:'42870324',doi:'10.1186/s42836-026-00439-x',journal:"Arthroplasty (London, England)",authors:"Yu Z, Wu B, Lin Y, Chen R, Bai G, Fang X, Zhang W, Huang Z",design:"Analisi retrospettiva monocentrica (First Affiliated Hospital, Fujian Medical University, Fuzhou) di pazienti operati di protesi monocompartimentale: cemento residuo diagnosticato con le immagini postoperatorie e classificato in estrusione residua (RCE) o frammentazione libera (FCF). Esito primario prevalenza e quadro clinico; secondari fattori di rischio ed esito del trattamento. Solo abstract letto: non risulta testo completo in PMC.",pop:"321 pazienti con UKA. Età, sesso, impianto, cementazione, follow-up e criteri di scelta della TC: non riportati nell'abstract.",results:"Cemento residuo in 84 pazienti su 321 (26,16%): RCE 66 (20,56%), FCF 18 (5,61%). RCE asintomatici o con lieve fastidio in 66 su 66 (100%); 6 FCF operati per dolore o limitazione. Polietilene più sottile: OR 2,59 (IC 95% 1,38-4,98; p=0,005). Rimozione artroscopica efficace nei sintomatici (esiti numerici non riportati).",concl:"Gli autori: il cemento residuo dopo UKA è più frequente di quanto noto, per lo più asintomatico; i frammenti liberi sintomatici richiedono un secondo intervento, la rimozione artroscopica sembra efficace, un inserto sottile è un fattore di rischio.",limits:"La TC è stata eseguita solo nei sintomatici: la prevalenza è una stima per difetto e la quota dei sintomatici è sovrastimata rispetto ai pazienti non esaminati · nessun gruppo di confronto, 18 FCF e 6 reinterventi: eventi pochi, IC non riportati sulla prevalenza · follow-up e tecnica di cementazione non riportati.",perte:"È la tua protesi monocompartimentale. Il dato dice che il cemento residuo è frequente nelle immagini, e che i frammenti liberi sono il caso da seguire. Cosa fare: nulla da cambiare; nel controllo di una UKA con dolore inspiegato, il cemento libero va nella lista (TC se la radiografia non basta). Non è un dato di esito dei tuoi pazienti."},
{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Bone Joint Res",h:"Passi al giorno dopo protesi: la monocompartimentale raggiunge i controlli, la totale resta sotto",v:"Studio osservazionale su UK Biobank (Imperial College, Londra), propensity-matched: 2283 partecipanti di 40-69 anni con accelerometro al polso per 7 giorni (TKA 860, UKA 162, THA 1168, resurfacing d'anca 93). Rispetto a controlli senza artrosi, TKA e THA restano meno attive, UKA e resurfacing sono simili ai controlli. Nel ginocchio UKA contro TKA: 9150 contro 7920 passi al giorno (+15,5%; p<0,001), cadenza più alta. Tutti i gruppi restano fra le fasce «somewhat active» e «active» (7500-12499 passi). IC non riportati nell'abstract.",ax:"Glynou, Musbahi, Sousi, Cobb",date:"ott 2026",meta:"studio osservazionale su UK Biobank, accelerometria a 7 giorni, 2283 partecipanti (TKA, UKA, THA, resurfacing) · [propensity-matched, livello non dichiarato]",pmid:'42866923',doi:'10.1302/2046-3758.1510.BJR-2025-0603.R1',journal:"Bone & joint research",authors:"Glynou SP, Musbahi O, Sousi S, Cobb JP",design:"Studio osservazionale entro UK Biobank (MSk Lab, Imperial College London): adulti di 40-69 anni con TKA, UKA, THA o resurfacing identificati da registri ospedalieri collegati, con accelerometria Axivity AX3 al polso per sette giorni. Esiti: passi giornalieri aggiustati (primario), cadenza di picco, attività da moderata a vigorosa, ENMO. Gruppi chirurgici accoppiati per propensity ai controlli non artrosici; confronto fra procedure con matching e regressione multivariata; sottogruppi sotto e sopra i 12 mesi. Solo abstract letto.",pop:"2283 partecipanti: TKA 860, UKA 162, THA 1168, resurfacing 93. Tempo mediano dall'intervento, quota di donne, indicazione: non riportati nell'abstract.",results:"Ginocchio: UKA 9150 contro TKA 7920 passi/die (+15,5%; p<0,001), cadenza più alta con UKA. Anca: resurfacing 10122 contro THA 9139 (+10,6%; p=0,032). Rispetto ai controlli: TKA e THA «persistentemente» più basse, UKA e resurfacing simili (valori e IC non riportati nell'abstract). Tutti i gruppi nella fascia 7500-12499 passi.",concl:"Gli autori: UKA e resurfacing si associano a più attività dopo l'intervento rispetto alle protesi totali; l'accelerometria offre una misura oggettiva e scalabile, da considerare accanto alla longevità dell'impianto nella scelta.",limits:"Osservazionale: l'indicazione alla UKA (artrosi compartimentale, pazienti più in forma) non è casuale, e il matching per propensity corregge solo le variabili misurate · un solo rilevamento di sette giorni, nessun PROM, nessuna sopravvivenza dell'impianto · IC non riportati nell'abstract; i risultati dicono quanto si muovono, non come stanno.",perte:"Riguarda la tua UKA. Il dato è coerente con una scelta compartimentale in chi ha l'indicazione, ma la differenza di 1230 passi al giorno nasce anche da chi viene scelto per la UKA. Cosa fare: nulla; è un argomento di colloquio sull'attività attesa, non un motivo per ampliare l'indicazione. Non dice nulla sulla durata dell'impianto."},
{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"J Long Term Eff Med Implants",h:"Cisti pretibiale dopo LCA: sei casi con viti di PLLA, tutti operati",v:"Serie retrospettiva (Atene, Attikon; livello non dichiarato): sei pazienti con cisti pretibiale su una coorte di 446 LCA con viti da interferenza in acido poli-L-lattico (PLLA). Comparsa a 2-4 anni con gonfiore e dolorabilità, senza infezione né allergia; alla RM cisti multiloculate e allargamento del tunnel tibiale accanto alle viti in degradazione. Tutti: sbrigliamento della cisti e rimozione della vite; istologia di infiammazione granulomatosa da corpo estraneo. Stabilità del ginocchio conservata (Lysholm, IKDC, Lachman stabili, Tegner in lieve calo), nessuna comunicazione con l'articolazione, nessuna recidiva. 6 su 446 (1,3%; IC 95% di Wilson 0,6-2,9%, calcolo mio).",ax:"Konstantas, Roustemis, Koulalis, Mastrokalos",date:"2026",meta:"serie retrospettiva, 6 pazienti su 446 LCA con viti di PLLA, cisti pretibiale · [livello non dichiarato]",pmid:'42870651',doi:'10.1615/JLongTermEffMedImplants.2025062524',journal:"Journal of long-term effects of medical implants",authors:"Konstantas OK, Roustemis A, Koulalis D, Mastrokalos D",design:"Revisione retrospettiva di sei casi di cisti pretibiale (University General Hospital Attikon, Atene) tratti da una coorte di 446 ricostruzioni del LCA con viti da interferenza bioassorbibili in PLLA. Valutazione di eziologia, quadro clinico e trattamento con radiografie, RM e istologia delle cisti rimosse. Solo abstract letto: non risulta testo completo in PMC. La data di pubblicazione su PubMed è solo l'anno (2026).",pop:"6 pazienti (da 446 LCA con viti PLLA). Età, sesso, innesto, tipo e posizione della vite, follow-up della coorte: non riportati nell'abstract.",results:"Sei cisti su 446 LCA (1,3%; IC 95% Wilson 0,6-2,9%, calcolo mio). Presentazione a 2-4 anni. Istologia: infiammazione granulomatosa con macrofagi, cellule giganti e necrosi focale. Dopo sbrigliamento e rimozione della vite: sintomi risolti, nessuna recidiva; Lysholm, IKDC e Lachman stabili, Tegner in lieve calo (valori non riportati).",concl:"Gli autori: la degradazione delle viti di PLLA può causare una reazione da corpo estraneo con cisti pretibiale; servono materiali bioassorbibili più compatibili.",limits:"Sei casi, nessun gruppo di confronto: la frequenza dipende dal denominatore (446) e dal follow-up della coorte, non riportato · non si sa se altre viti o la tecnica del tunnel tibiale abbiano avuto un ruolo · valori dei punteggi non riportati.",perte:"Dipende dalla fissazione tibiale che usi: l'abstract riguarda le viti da interferenza in PLLA. Cosa fare: se in un tuo LCA con vite bioassorbibile compare una tumefazione pretibiale a distanza di anni, questa è una causa da considerare, con RM, prima di pensare all'infezione. Nessun dato su altri materiali."},
{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"SICOT J",h:"Protesi femororotulea robotica: libera da revisione al 91,6% a 24 mesi, senza gruppo di controllo",v:"Studio retrospettivo monocentrico (Lione, Croix-Rousse; livello IV): 30 pazienti (35 ginocchia), protesi femororotulea con robot (MAKO) per artrosi femororotulea isolata, 2021-2024, follow-up medio 15,7 ± 8,5 mesi. Reinterventi 8,6% (3/35), due conversioni a TKA; sopravvivenza libera da revisione 96,7% (IC 95% 90,2-100,0) a 12 mesi e 91,6% (IC 95% 80,1-100,0) a 24 e 36 mesi. KSS da 110,7 ± 21,1 a 163,7 ± 22,3 (p<0,001); lateralizzazione rotulea da 4,7 ± 3,8 a 0,8 ± 1,8 mm (p<0,001); rientro allo sport 78,3% degli attivi.",ax:"Fogacci, Favroul, Andriollo, Longlune, Batailler, Servien, Lustig",date:"ott 2026",meta:"serie retrospettiva monocentrica, 30 pazienti (35 ginocchia), protesi femororotulea con robot, follow-up medio 16 mesi · [livello IV]",pmid:'42867179',doi:'10.1051/sicotj/2026070',journal:"SICOT-J",authors:"Fogacci A, Favroul C, Andriollo L, Longlune P, Batailler C, Servien E, Lustig S",design:"Studio retrospettivo monocentrico (Croix-Rousse Hospital, Hospices Civils de Lyon; FIFA Medical Center of Excellence), pazienti consecutivi con protesi femororotulea isolata assistita da robot su immagini (RA-PFA) fra novembre 2021 e ottobre 2024, minimo 12 mesi. Esiti primari sopravvivenza, sopravvivenza senza reintervento e complicanze; secondari KSS, mobilità, rientro allo sport, parametri radiografici e concordanza fra piano MAKO e posizionamento finale. Kaplan-Meier. Solo abstract letto (testo in PMC: PMC13661128, non aperto).",pop:"30 pazienti (35 ginocchia, 5 bilaterali), età media 61,3 ± 12,2 anni, BMI 25,3 ± 5,2; Iwano III-IV 91,4%. Follow-up medio 15,7 ± 8,5 mesi.",results:"Reintervento 8,6% (3/35), due conversioni a TKA. Sopravvivenza libera da revisione: 96,7% (IC 95% 90,2-100,0) a 12 mesi; 91,6% (IC 95% 80,1-100,0) a 24 e 36 mesi. KSS 110,7 ± 21,1 → 163,7 ± 22,3 (p<0,001); mobilità mediana 130°; rientro allo sport 78,3% degli attivi; lateralizzazione rotulea 4,7 ± 3,8 → 0,8 ± 1,8 mm (p<0,001); concordanza della taglia dei componenti 100%.",concl:"Gli autori: risultati precoci incoraggianti, con buoni guadagni funzionali e allineamento femororotuleo migliorato; il contributo del robot non è stabilito senza un gruppo convenzionale.",limits:"Nessun gruppo convenzionale: il ruolo del robot non si può isolare (lo dicono gli autori) · 35 ginocchia, 3 eventi: l'IC della sopravvivenza a 24 mesi arriva a 80,1% · follow-up medio di 16 mesi, troppo breve per la PFA (il fallimento tipico è la progressione dell'artrosi tibiofemorale: nota mia, non dell'abstract).",perte:"Robot MAKO, non VELYS, e protesi femororotulea, che non fai. Cosa fare: nulla; è un dato di sopravvivenza precoce su un'indicazione rara, senza confronto. Conta come sfondo se un paziente con artrosi femororotulea isolata chiede della protesi robotica."},
{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Musculoskelet Surg",h:"TKA: apertura mediale di 1,5 mm alla radiografia del primo giorno, esiti peggiori nelle donne sotto i 70 anni",v:"Coorte retrospettiva (Melbourne, Western Health; livello non dichiarato): 637 TKA primarie allineate meccanicamente (556 pazienti, 2012-2017), follow-up mediano 5,4 anni, PROM a ≥3 anni. Differenza mediana fra spazio laterale e mediale da 4,9 mm preoperatori a 0 mm alla radiografia in scarico del primo giorno. Nelle donne <70 anni ogni mm di apertura mediale si associa a 1 punto OKS in meno e 2,4 punti EQ-5D VAS in meno; un aumento del 100% del rapporto mediale/laterale a 8,8 punti OKS in meno (<60 anni) e 4 punti (60-70 anni). Apertura mediale ≥1,5 mm prevede OKS ed EQ-5D peggiori; negli uomini nessuna associazione. IC non riportati.",ax:"Keltz, Ng, Spiers, Tirosh, Almaslmani, Vorgin, Tran",date:"ott 2026",meta:"coorte retrospettiva, 637 TKA allineate meccanicamente, radiografia del primo giorno e OKS a ≥3 anni · [livello non dichiarato]",pmid:'42870131',doi:'10.1007/s12306-026-00973-6',journal:"Musculoskeletal surgery",authors:"Keltz E, Ng E, Spiers L, Tirosh O, Almaslmani S, Vorgin S, Tran P",design:"Coorte retrospettiva (Western Health, Melbourne) di TKA primarie con allineamento meccanico 2012-2017: gap mediale e laterale misurati in digitale sulle radiografie AP e laterali supine in scarico del primo giorno; asimmetria come differenza assoluta e come rapporto mediale/laterale. Esiti Oxford Knee Score, VAS del dolore ed EQ-5D VAS a ≥3 anni. Regressioni lineari e logistiche multivariabili aggiustate per età, sesso, BMI. Solo abstract letto: non risulta testo completo in PMC.",pop:"637 TKA in 556 pazienti, 2012-2017, follow-up mediano 5,4 anni. Età media, quota di donne, impianto, tasso di risposta ai PROM: non riportati nell'abstract.",results:"Differenza mediana laterale-mediale 4,9 mm → 0 mm. Donne <70 anni: -1 punto OKS e -2,4 punti EQ-5D VAS per ogni mm di apertura mediale; rapporto mediale/laterale +100%: -8,8 punti OKS (<60 anni), -4 (60-70). Apertura mediale ≥1,5 mm: OKS ed EQ-5D peggiori; apertura laterale lieve: esiti simili alle ginocchia simmetriche. Uomini: nessuna associazione significativa. IC e p non riportati nell'abstract.",concl:"Gli autori: un'apertura mediale ≥1,5 mm (o rapporto ≥100%) alla radiografia del primo giorno prevede esiti peggiori a medio termine nelle donne <70 anni; lo squilibrio coronale precoce ha rilevanza clinica duratura in quel gruppo.",limits:"Sottogruppo (donne <70 anni) con associazione assente negli uomini: gli abstract non dicono se l'analisi per sesso ed età fosse pianificata, e senza IC il rischio di falso positivo non è valutabile · radiografia in scarico del primo giorno: misura di gap non equivalente a un bilanciamento in tensione · TKA con allineamento meccanico manuale, non robotica; effetti di 1 punto OKS per mm, probabilmente sotto la differenza clinicamente rilevante (valutazione mia).",perte:"Allineamento meccanico manuale, non il tuo VELYS. Cosa fare: nulla; è un'ipotesi su un sottogruppo, con associazione a 1 punto OKS per mm, di entità clinicamente piccola. Utile solo come motivo per guardare il gap medio-laterale nelle radiografie di controllo del primo giorno nelle pazienti più giovani."},
{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"Bone Jt Open",h:"Revisione di protesi di ginocchio: consenso Delphi su una classificazione dei difetti ossei alla TC",v:"Studio Delphi in tre fasi (Nimega, Sint Maartenskliniek, con esperti internazionali; livello non dichiarato): cinque interviste hanno prodotto 29 affermazioni, inviate a 56 esperti di revisione di ginocchio. Hanno risposto 37 al primo round e 34 al secondo. Consenso (≥80% di accordo) sul 93% delle affermazioni: la classificazione deve guidare pianificazione e scelta dell'impianto, la TC migliora la valutazione del difetto, definizione condivisa di difetto osseo. Nessun consenso su quali riferimenti definiscano le zone anatomiche (epifisi, metafisi, diafisi).",ax:"de Bondt, van Laarhoven, van Hellemondt, Porteous, Tuijthof, Heesterbeek, Adravanti, Alvand, d'Amato et al.",date:"ott 2026",meta:"consenso Delphi (interviste e due round), 56 esperti invitati (34 al secondo round), classificazione TC dei difetti ossei in revisione di protesi di ginocchio · [livello non dichiarato]",pmid:'42852545',doi:'10.1302/2633-1462.710.BJO-2026-0188.R1',journal:"Bone & joint open",authors:"de Bondt MR, van Laarhoven SN, van Hellemondt GG, Porteous A, Tuijthof GJM, Heesterbeek PJC, Adravanti P, Alvand A, d'Amato M, Baldini A, Batailler C, Bellemans J, Boettner F, Campi S, Groes SV, Halder A, Hirschmann M, Hofmann S, Jackson W, Jones G, Keijser L, Kempen RV, Klauser W, Koch P, León-Muñoz VJ, London N, Lustig S, Luyckx T, Oussedik S, Phillips J, Rossi S, Rosso F, Thienpont E, Vandenneucker H, Waterson B, Wagenaar FC, Wensen RV, Windt T, Zambianchi F",design:"Studio Delphi strutturato in tre fasi: cinque interviste a esperti internazionali di revisione del ginocchio per formulare 29 affermazioni, poi due round di questionario (56 invitati al primo, 37 al secondo). Soglia di consenso ≥80% di accordo, su definizione del difetto osseo, imaging e valutazione per zone. Obiettivo: i principi e i criteri di una nuova classificazione dei difetti (BDC) basata sulla TC. Solo abstract letto.",pop:"Esperti internazionali di revisione del ginocchio: 56 invitati, 37 rispondenti al primo round, 34 al secondo. Composizione per paese, anni di esperienza, casistica: non riportati nell'abstract.",results:"Consenso raggiunto sul 93% delle affermazioni dopo i due round (calcolo mio: 27 su 29). Accordo che la BDC debba guidare la pianificazione chirurgica e la scelta dell'impianto e che la TC migliori la valutazione dei difetti; consenso sulla definizione di difetto osseo. Nessun consenso sui riferimenti anatomici che definiscono le zone.",concl:"Gli autori: valutazione TC e valutazione distinta delle zone anatomiche sono essenziali in una nuova classificazione, ma manca consenso sulla definizione delle zone; la classificazione dovrebbe servire a pianificazione e impianto.",limits:"Consenso fra esperti, non prova: nessun dato di paziente né validazione della classificazione · i partecipanti (34 al secondo round) sono selezionati da chi propone lo studio, la composizione non è riportata · la parte più utile per una classificazione, i riferimenti delle zone, non ha raggiunto il consenso.",perte:"Revisione di protesi di ginocchio: non è la tua chirurgia. Cosa fare: nulla. Si legge come segnale di dove sta andando la pianificazione TC dei difetti, e come promemoria che la classificazione ancora non esiste."}];
var SUGGQ=[{"k": "kol", "n": "Sébastien Lustig (Croix-Rousse Hospital, Hospices Civils de Lyon, Francia)", "w": "Francia: ultimo firmatario della serie di oggi sulla protesi femororotulea con robot (PMID 42867179; afferenza letta nei metadati PubMed). Corrispondenza tecnica con la protesi robotica che usi (VELYS) e con la monocompartimentale. Sostituisce Jorge Chahla (14 ottobre, nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Giovedì 15 ottobre. Oggi nove lavori, nessuna scheda rossa e nessuna arancione: nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi, nessun nuovo consensus o linea guida nella tua pratica. Giornata di tipo leggero, perché il giorno prima aveva già preso gran parte di ciò che era entrato in PubMed. Il lavoro del giorno tocca la pendenza tibiale posteriore, di cui ti occupi con le correzioni di slope: uno studio radiografico di Zagabria su tremilatrecentotrentasette ginocchia artrosiche. Il k-means sulla sola pendenza trova due gruppi, uno piatto intorno a tre gradi e mezzo, con il cinquantasei per cento delle ginocchia, e uno ripido intorno a otto gradi e mezzo. Nelle quattrocentosessantaquattro ginocchia con il CPAK nessuna singola categoria si associa a un gruppo, ma l'apice distale della rima articolare cade più spesso nel gruppo ripido, cinquantaquattro per cento contro trentanove. Il limite è che il k-means divide sempre, che il CPAK c'è solo nel quattordici per cento circa dei casi, e che non c'è nessun esito clinico: la conclusione pratica è misurare la pendenza di profilo e non dedurla dall'asse frontale. Poi tre lavori sul crociato e sulla protesi monocompartimentale. Una coorte di quarantotto operati di LCA con residuo conservato a sospensione in tensione: a tre mesi il segnale dell'innesto alla risonanza è diverso, a sei mesi non lo è più, e i punteggi sono uguali. Uno studio di laboratorio su trentasei ginocchia: nei pazienti con lassità generalizzata, e solo con la soglia di Beighton più alta, il semitendinoso contiene più collagene di tipo tre; innesto diverso dal tuo, nessuna prova meccanica. E una serie su trecentoventuno protesi monocompartimentali, con cemento residuo nelle immagini in ventisei pazienti ogni cento, quasi sempre senza sintomi; i frammenti liberi sono il caso da seguire, sei reinterventi su diciotto. Il quarto lavoro verde viene da UK Biobank: chi ha una protesi monocompartimentale fa in media novemilacentocinquanta passi al giorno contro settemilanovecentoventi con la totale, ma l'indicazione non è casuale. Quattro lavori fuori dalla tua tecnica: sei casi di cisti pretibiale da viti di acido polilattico dopo LCA, una serie lionese di protesi femororotulea con robot, un'associazione fra apertura mediale alla radiografia del primo giorno e punteggi dopo protesi totale nelle donne sotto i settant'anni, e un consenso Delphi sulla classificazione dei difetti ossei alla TC nella revisione di protesi. Nessuna tensione si è mossa: la pendenza fa da sfondo alla prima, senza toccarla. Nella seconda pagina undici brevi e tre proposte fuori dal solito, fra cui un robot cinese per la monocompartimentale a piattaforma aperta.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Giovedì quindici ottobre. Nove lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo nuovo, nessuna ritrattazione che ti riguardi, nessun consensus nella tua pratica. È una giornata leggera, perché ieri è già entrato molto."}, {"chi": "B", "t": "Quindi il lavoro del giorno?"}, {"chi": "A", "t": "La pendenza tibiale posteriore. Uno studio radiografico di Zagabria su oltre tremilatrecento ginocchia artrosiche: il k-means trova due gruppi, uno piatto intorno a tre gradi e mezzo e uno ripido intorno a otto gradi e mezzo."}, {"chi": "B", "t": "E la classificazione CPAK li separa?"}, {"chi": "A", "t": "No, non per singola categoria. Raggruppando per orientamento della rima, l'apice distale cade più spesso nel gruppo ripido, cinquantaquattro per cento contro trentanove."}, {"chi": "B", "t": "Quindi per le tue correzioni di slope e per il piano con il VELYS la pendenza si misura di profilo."}, {"chi": "A", "t": "Esatto. Con i limiti che il k-means divide sempre, che il CPAK c'è solo nel quattordici per cento circa delle ginocchia e che non c'è nessun esito clinico. È anche artrosi, età mediana sessantanove anni, non il tuo crociato giovane."}, {"chi": "B", "t": "Poi il crociato."}, {"chi": "A", "t": "Una coorte di quarantotto operati con residuo conservato a sospensione in tensione: a tre mesi l'innesto è diverso alla risonanza, a sei mesi non più. E uno studio di laboratorio sul semitendinoso: più collagene di tipo tre nei pazienti molto lassi, ma solo con una soglia su tre."}, {"chi": "B", "t": "Il semitendinoso non è il mio innesto."}, {"chi": "A", "t": "Giusto. Vale come ipotesi sul perché la lassità generalizzata pesa con l'hamstring, non come dato sul tuo retto femorale."}, {"chi": "B", "t": "E la protesi monocompartimentale?"}, {"chi": "A", "t": "Due cose. Una serie su trecentoventuno protesi: cemento residuo nelle immagini in ventisei pazienti ogni cento, quasi sempre silente, ma i frammenti liberi hanno richiesto sei reinterventi. E UK Biobank: con la monocompartimentale si fanno più passi che con la totale, anche se l'indicazione non è casuale."}, {"chi": "B", "t": "Il resto?"}, {"chi": "A", "t": "Fuori dalla tua tecnica: le cisti pretibiali da viti di acido polilattico, una serie lionese di protesi femororotulea con robot, un'associazione fra apertura mediale e punteggi dopo protesi totale e un consenso Delphi sui difetti ossei in revisione. Nessuna tensione si è mossa."}];
